'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "config": {
    "background": "#ffffff",
    "font": "Arial, Helvetica, sans-serif",
    "view": {
      "stroke": null
    },
    "axis": {
      "domainColor": "#404040",
      "domainWidth": 1.5,
      "ticks": false,
      "grid": false,
      "labelColor": "#555555",
      "labelFont": "Arial",
      "labelFontSize": 11,
      "title": null
    },
    "legend": {
      "disable": true
    }
  },
  "title": {
    "anchor": "start",
    "font": "Arial",
    "fontSize": 13.5,
    "color": "#404040",
    "subtitleFont": "Arial",
    "subtitleFontSize": 12.5,
    "subtitleColor": "#404040",
    "offset": 16,
    "text": "Daten-WG Brewery",
    "subtitle": [
      "P&L bridge in kEUR",
      "YTD Jan–Sep 2026 · AC vs PY"
    ]
  },
  "hconcat": [
    {
      "width": 230,
      "height": {
        "step": 27
      },
      "data": {
        "name": "dataset"
      },
      "transform": [
        {
          "window": [
            {
              "op": "row_number",
              "as": "vord"
            }
          ]
        },
        {
          "window": [
            {
              "op": "lead",
              "field": "L1",
              "as": "leadK"
            }
          ],
          "sort": [
            {
              "field": "vord"
            }
          ]
        },
        {
          "window": [
            {
              "op": "sum",
              "field": "AC WF kEUR",
              "as": "cumA"
            }
          ],
          "sort": [
            {
              "field": "vord"
            }
          ],
          "frame": [
            null,
            0
          ],
          "ignorePeers": true
        },
        {
          "window": [
            {
              "op": "sum",
              "field": "PY WF kEUR",
              "as": "cumR"
            }
          ],
          "sort": [
            {
              "field": "vord"
            }
          ],
          "frame": [
            null,
            0
          ],
          "ignorePeers": true
        },
        {
          "calculate": "datum[\"CK_RowType\"]===''sum''",
          "as": "sum"
        },
        {
          "calculate": "datum.sum ? 0 : datum.cumA - datum[\"AC WF kEUR\"]",
          "as": "s"
        },
        {
          "calculate": "datum.cumA",
          "as": "e"
        },
        {
          "calculate": "datum.sum ? 0 : datum.cumR - datum[\"PY WF kEUR\"]",
          "as": "sR"
        },
        {
          "calculate": "datum.cumR",
          "as": "eR"
        },
        {
          "calculate": "datum.sum ? datum.cumR : datum[\"PY WF kEUR\"]",
          "as": "refv"
        },
        {
          "calculate": "datum.sum ? datum.cumA - datum.cumR : datum[\"AC WF kEUR\"] - datum[\"PY WF kEUR\"]",
          "as": "d"
        },
        {
          "calculate": "datum.refv > 0 ? datum.d / datum.refv * 100 : null",
          "as": "rv"
        }
      ],
      "encoding": {
        "y": {
          "field": "L1",
          "type": "nominal",
          "sort": null,
          "axis": {
            "labelPadding": 8
          }
        }
      },
      "layer": [
        {
          "transform": [
            {
              "filter": "datum.leadK != null"
            }
          ],
          "mark": {
            "type": "rule",
            "color": "#c2c2c2",
            "strokeWidth": 1
          },
          "encoding": {
            "x": {
              "field": "e",
              "type": "quantitative",
              "axis": {
                "domain": false,
                "ticks": false,
                "labels": false,
                "grid": false,
                "title": null
              }
            },
            "y2": {
              "field": "leadK",
              "type": "nominal"
            }
          }
        },
        {
          "mark": {
            "type": "bar",
            "size": 15,
            "fill": "#404040",
            "tooltip": {
              "content": "data"
            }
          },
          "encoding": {
            "x": {
              "field": "s",
              "type": "quantitative",
              "axis": {
                "domain": false,
                "ticks": false,
                "labels": false,
                "grid": false,
                "title": null
              }
            },
            "x2": {
              "field": "e"
            }
          }
        },
        {
          "transform": [
            {
              "filter": "datum.sum"
            }
          ],
          "mark": {
            "type": "text",
            "dx": 6,
            "align": "left",
            "fontSize": 11,
            "font": "Arial",
            "color": "#404040",
            "fontWeight": "bold"
          },
          "encoding": {
            "x": {
              "field": "e",
              "type": "quantitative",
              "axis": {
                "domain": false,
                "ticks": false,
                "labels": false,
                "grid": false,
                "title": null
              }
            },
            "text": {
              "field": "e",
              "type": "quantitative",
              "format": ",.0f"
            }
          }
        },
        {
          "transform": [
            {
              "filter": "!datum.sum && datum.e >= datum.s"
            }
          ],
          "mark": {
            "type": "text",
            "dx": 6,
            "align": "left",
            "fontSize": 11,
            "font": "Arial",
            "color": "#404040"
          },
          "encoding": {
            "x": {
              "field": "e",
              "type": "quantitative",
              "axis": {
                "domain": false,
                "ticks": false,
                "labels": false,
                "grid": false,
                "title": null
              }
            },
            "text": {
              "field": "AC WF kEUR",
              "type": "quantitative",
              "format": "+,.0f"
            }
          }
        },
        {
          "transform": [
            {
              "filter": "!datum.sum && datum.e < datum.s"
            }
          ],
          "mark": {
            "type": "text",
            "dx": -6,
            "align": "right",
            "fontSize": 11,
            "font": "Arial",
            "color": "#404040"
          },
          "encoding": {
            "x": {
              "field": "e",
              "type": "quantitative",
              "axis": {
                "domain": false,
                "ticks": false,
                "labels": false,
                "grid": false,
                "title": null
              }
            },
            "text": {
              "field": "AC WF kEUR",
              "type": "quantitative",
              "format": "+,.0f"
            }
          }
        }
      ]
    },
    {
