    }
  ],
  "spacing": 26,
  "resolve": {
    "scale": {
      "y": "independent"
    }
  },
  "description": "Generated with the Daten-WG Business Chart Builder (IBCS-inspired notation), fields mapped to the BreweryFinance model."
